const body = $input.first().json.body || $input.first().json;
const demoMode = body.demo_mode === true || body.demo_mode === 'true';
const companyName = body.company_name || body.company || '';
if (!demoMode && !companyName) throw new Error('Missing required field: company_name');
const company = companyName || 'Stripe';
return [{ json: {
  user_id: body.user_id || 'demo-user',
  company_name: company,
  target_role: body.target_role || 'Senior ML Engineer',
  channel: body.channel || 'email',
  demo_mode: demoMode,
  session_id: body.session_id || `ci_${Date.now()}`,
  news_query: `${company} layoffs OR funding OR culture OR leadership 2025`,
  web_query: `${company} company overview engineering culture tech stack site:${company.toLowerCase().replace(/\s/g,'')}.com OR site:linkedin.com/company`,
  contact_query: `"${company}" recruiter OR "hiring manager" OR "technical recruiter" site:linkedin.com`,
  received_at: new Date().toISOString()
}}];

const r = $input.first().json;
const input = $('\u2705 Validate & Prepare Input').first().json;

if (input.demo_mode) {
  const demoNews = [
    { title: `${input.company_name} raises $500M Series D at $8B valuation`, date: '2025-03-15', sentiment: 'positive' },
    { title: `${input.company_name} expands NYC engineering team by 200 roles`, date: '2025-02-20', sentiment: 'positive' },
    { title: `${input.company_name} CEO on building AI-first infrastructure`, date: '2025-01-10', sentiment: 'neutral' }
  ];
  return [{ json: { news: demoNews, sentiment_score: 72, source: 'demo' } }];
}

const articles = r.news || [];
const negativeWords = ['layoff', 'fired', 'lawsuit', 'scandal', 'decline', 'loss', 'cut', 'downsize'];
const positiveWords = ['funding', 'growth', 'hire', 'expand', 'launch', 'award', 'profit', 'raise'];

let score = 50;
const processed = articles.map(a => {
  const text = (a.title + ' ' + (a.snippet || '')).toLowerCase();
  const neg = negativeWords.filter(w => text.includes(w)).length;
  const pos = positiveWords.filter(w => text.includes(w)).length;
  score += (pos * 8) - (neg * 12);
  return { title: a.title, date: a.date, sentiment: neg > pos ? 'negative' : pos > 0 ? 'positive' : 'neutral', source: a.source };
});

return [{ json: { news: processed, sentiment_score: Math.max(0, Math.min(100, score)), source: 'serper' } }];

const r = $input.first().json;
const input = $('\u2705 Validate & Prepare Input').first().json;

if (input.demo_mode) {
  return [{ json: {
    company_overview: `${input.company_name} is a leading fintech company building payment infrastructure for the internet. Known for developer-friendly APIs and strong engineering culture.`,
    glassdoor_rating: 4.2,
    tech_stack: ['Python', 'Go', 'Kubernetes', 'AWS', 'PostgreSQL', 'Redis'],
    company_size: '5,000-10,000',
    headquarters: 'San Francisco, CA',
    source: 'demo'
  } }];
}

// You.com returns hits with richer content than Serper snippets
const hits = r.hits || r.web?.results || r.results || [];
const snippets = hits.map(h => {
  const parts = [h.title || '', h.description || ''];
  if (h.snippets) parts.push(...h.snippets);
  return parts.join(' ');
}).join(' ').slice(0, 1000);

return [{ json: {
  company_overview: snippets || `${input.company_name} is a technology company.`,
  glassdoor_rating: null,
  tech_stack: [],
  source: 'youcom'
} }];

const r = $input.first().json;
const input = $('\u2705 Validate & Prepare Input').first().json;

if (input.demo_mode) {
  return [{ json: { contacts: [
    { name: 'Sarah Chen', title: 'Senior Technical Recruiter', email: null, linkedin: 'linkedin.com/in/sarahchen', confidence: 85, source: 'demo' },
    { name: 'Marcus Johnson', title: 'Engineering Manager, ML Platform', email: null, linkedin: 'linkedin.com/in/marcusjohnson', confidence: 78, source: 'demo' },
    { name: 'Priya Patel', title: 'Head of ML Engineering', email: null, linkedin: 'linkedin.com/in/priyapatel', confidence: 72, source: 'demo' }
  ], total_found: 3, source: 'demo' } }];
}

// Parse You.com search results for LinkedIn profiles
const hits = r.hits || r.web?.results || r.results || [];
const contacts = hits
  .filter(h => h.url && h.url.includes('linkedin.com/in/'))
  .slice(0, 8)
  .map((h, i) => {
    const nameMatch = h.title?.match(/^([^|\-\u2014]+)/);
    const name = nameMatch ? nameMatch[1].trim() : 'Unknown';
    const titleMatch = h.description?.match(/(?:is a|works as|\u2014|-)\s*([^.]+?)(?:\s+at|$)/i);
    const title = titleMatch ? titleMatch[1].trim() : (h.description?.split('.')[0] || 'Unknown');
    return {
      name,
      title,
      email: null,
      linkedin: h.url,
      confidence: Math.max(50, 90 - i * 8),
      source: 'youcom'
    };
  })
  .filter(c => c.name !== 'Unknown' && c.name.length > 2);

return [{ json: { contacts, total_found: contacts.length, source: 'youcom' } }];

const items = $input.all();
const sentiment = items.find(i => i.json.sentiment_score !== undefined)?.json || {};
const profile = items.find(i => i.json.company_overview !== undefined)?.json || {};
const contacts = items.find(i => i.json.contacts !== undefined)?.json || {};
const input = $('\u2705 Validate & Prepare Input').first().json;

const healthScore = Math.round(
  (sentiment.sentiment_score || 50) * 0.4 +
  ((profile.glassdoor_rating || 3.5) / 5 * 100) * 0.3 +
  (contacts.total_found > 0 ? 80 : 40) * 0.3
);

return [{ json: {
  ...input,
  news: sentiment.news || [],
  sentiment_score: sentiment.sentiment_score || 50,
  company_overview: profile.company_overview || '',
  glassdoor_rating: profile.glassdoor_rating,
  tech_stack: profile.tech_stack || [],
  contacts: contacts.contacts || [],
  health_score: healthScore
}}];

